    }

    @Test
    void payDeclinedReleasesReservationAndCoupon() {
        long pid = product(1_000, 5);
        String code = coupon("FIXED", 100, 0, null, 3);
        long oid = order("u", UUID.randomUUID().toString(), pid, 2, code).body().get("id").asLong();
